E = []

E.append(tract("tract-corticospinal", "Corticospinal tract", "projection",
 "The corticospinal tract is the great descending motor pathway from the precentral gyrus, premotor and supplementary motor cortex and the postcentral gyrus to the spinal cord, reconstructed here from diffusion tractography as the bundle that runs through the corona radiata, the posterior limb of the internal capsule, the middle of the crus cerebri, the basis pontis and the medullary pyramid. Most of its fibers cross in the pyramidal decussation to form the lateral corticospinal tract, so a lesion above the decussation weakens the opposite side and one below it the same side. It is the substrate of the upper motor neuron syndrome and of capsular, pontine and medullary strokes, and its integrity on tractography predicts recovery of hand function after stroke.",
 "From the motor cortex through the corona radiata, converging into the posterior limb of the internal capsule (face anterior, leg posterior), the middle three-fifths of the crus cerebri, the scattered bundles of the basis pontis and the pyramid of the medulla, where 85-90 percent cross to the contralateral lateral column and the rest descend uncrossed in the anterior column.",
 "It carries the voluntary motor command, especially for fractionated finger movements and for the face and tongue through its corticobulbar companions; its monosynaptic connections to spinal motor neurons are what make skilled hand movement possible, and its collaterals to the dorsal horn and the brainstem set the gain of reflexes. Its loss produces weakness with the upper motor neuron pattern of extensor-flexor imbalance, spasticity from loss of accompanying corticoreticular fibers, hyperreflexia and the extensor plantar response. The tractography reconstruction follows the bundle from cortex to the caudal medulla and shows its somatotopy in the capsule and the peduncle.",
 ["artery-mca", "arteries-lenticulostriate", "artery-anterior-choroidal", "artery-basilar", "arteries-pontine", "artery-vertebral", "anterior-spinal-artery"],
 [mview("coronal", "tract-corticospinal-l", "corticospinal tract from the motor cortex through the internal capsule to the brainstem"), mview("axial", "tract-corticospinal-r", "corticospinal fibers in the posterior limb of the internal capsule")],
 "On diffusion tractography a dense blue (superoinferior) bundle from the precentral gyrus through the posterior limb and the cerebral peduncle to the pyramid; on FLAIR it is often slightly bright in the posterior limb in healthy adults, a normal finding not to be mistaken for disease.",
 [pathol("Capsular or pontine infarct with hemiparesis", "MRI", "Restricted diffusion in the posterior limb or basis pontis; subsequent Wallerian degeneration of the tract appears as T2 hyperintensity and atrophy of the ipsilateral peduncle and pyramid over months.", sequence="DWI", timing="Wallerian change visible on DWI within days and on T2 by 4-10 weeks"),
  pathol("Amyotrophic lateral sclerosis", "MRI", "Symmetric T2/FLAIR hyperintensity along the corticospinal tracts from the corona radiata to the brainstem and T2 hypointensity of the precentral cortex; supportive, not diagnostic.", sequence="FLAIR"),
  pathol("Tumor displacing the corticospinal tract", "MRI", "Tractography shows the bundle displaced or infiltrated by a glioma, guiding the surgical corridor; distance to the tract predicts postoperative weakness.", sequence="n/a")],
 [("Contralateral spastic hemiparesis (lesion above the decussation)", "contralateral", "Interruption of crossed corticospinal fibers"), ("Ipsilateral weakness (lesion below the decussation)", "ipsilateral", "Interruption after the fibers have crossed"), ("Loss of fine finger movements out of proportion to strength", "contralateral", "Loss of the corticomotoneuronal component")],
 ["Pronator drift, finger tapping and grip release", "Tone, reflexes and the plantar response", "Pattern of weakness: extensors in the arm and flexors in the leg"],
 ["The corticospinal tract crosses at the bottom of the medulla: above it, the weakness is on the other side", "Wallerian degeneration of the tract after a stroke is visible on MRI and explains a shrunken peduncle", "Tractography of this bundle is the most trusted map in tumor surgery"],
 [S(4, 152, 160), S(5, 185, 199), S(7, 262, 268), B(4, 33, 36), B(28, 289, 292)], synonyms=["pyramidal tract", "CST"], mesh_ids=T("tract-corticospinal"), pathways=["pathway-lateral-corticospinal", "pathway-anterior-corticospinal"], syndromes=["syn-lacunar-pure-motor", "syn-als-pattern", "syn-locked-in", "syn-dejerine-medial-medullary"],
 territories=["territory-mca-major", "territory-lateral-lenticulostriate", "territory-basilar"], parent="corona-radiata",
 afferents=[("Precentral gyrus (area 4) and premotor cortex", "origin"), ("Postcentral gyrus and parietal cortex", "origin (sensory fibers to the dorsal horn)")],
 efferents=[("Spinal motor neurons and interneurons", "lateral and anterior corticospinal tracts"), ("Dorsal horn and dorsal column nuclei", "corticospinal collaterals")]))

E.append(tract("tract-corticobulbar", "Corticobulbar tract", "projection",
 "The corticobulbar tract carries the motor command from the face, tongue and larynx areas of the precentral gyrus and the premotor cortex to the motor nuclei of the cranial nerves in the brainstem, running with the corticospinal tract through the genu and posterior limb of the internal capsule and the medial crus cerebri before leaving it at each level to reach the trigeminal, facial, ambiguus and hypoglossal nuclei. Because most nuclei receive both hemispheres, a unilateral lesion produces only lower facial weakness and mild tongue and palatal deviation, whereas bilateral lesions produce the pseudobulbar palsy of spastic dysarthria, dysphagia and emotional lability. The reconstruction shows the bundle from the lateral motor cortex to the pons and medulla.",
 "From the ventral precentral gyrus and frontal operculum through the corona radiata into the genu of the internal capsule, then the medial part of the middle of the crus cerebri, descending in the basis pontis and pyramid and sending crossed and uncrossed fibers to the trigeminal motor nucleus, the facial nucleus, the nucleus ambiguus and the hypoglossal nucleus, largely through interneurons of the reticular formation.",
 "It provides voluntary control of chewing, facial expression, phonation, swallowing and tongue movement, with bilateral supply to most nuclei except the lower facial subnucleus and part of the hypoglossal nucleus, which receive mainly crossed fibers; it also carries the corticoreticular fibers that inhibit the brainstem reflex centers for laughing and crying, so bilateral loss releases pathological emotional expression. Unilateral damage gives contralateral lower facial weakness and transient dysarthria; bilateral damage from repeated strokes, motor neuron disease or bilateral opercular lesions gives a slow, strained voice, a brisk jaw jerk and a tongue that cannot move but does not waste.",
 ["artery-mca", "arteries-lenticulostriate", "artery-anterior-choroidal", "artery-basilar", "arteries-pontine"],
 [mview("coronal", "tract-corticobulbar-l", "corticobulbar fibers from the face area to the brainstem"), mview("axial", "tract-corticobulbar-r", "corticobulbar tract in the genu of the internal capsule")],
 "Tractography shows a bundle from the lateral precentral gyrus converging into the genu of the internal capsule medial to the corticospinal fibers and descending in the medial crus; it cannot be separated from the corticospinal tract on conventional MRI.",
 [pathol("Pseudobulbar palsy from bilateral capsular or pontine infarcts", "MRI", "Bilateral lacunes in the genu or basis pontis with spastic dysarthria, dysphagia, brisk jaw jerk and emotional lability.", sequence="FLAIR"),
  pathol("Amyotrophic lateral sclerosis (bulbar onset)", "MRI", "Corticospinal and corticobulbar tract hyperintensity with precentral hypointensity; EMG shows the lower motor neuron component in the tongue.", sequence="FLAIR"),
  pathol("Central facial palsy from a small capsular infarct", "MRI", "Restricted diffusion in the genu of the internal capsule with contralateral lower facial weakness and dysarthria.", sequence="DWI")],
 [("Contralateral lower facial weakness sparing the forehead", "contralateral", "Loss of the crossed projection to the lower facial subnucleus"), ("Pseudobulbar palsy when bilateral", "bilateral", "Loss of bilateral supranuclear control of the bulbar nuclei"), ("Pathological laughing and crying", "bilateral", "Loss of corticoreticular inhibition of brainstem emotional-expression centers")],
 ["Forehead wrinkling versus lower facial movement", "Jaw jerk, palatal elevation, tongue movement and speed, and emotional lability", "Swallowing assessment before oral intake in bilateral lesions"],
 ["A brisk jaw jerk with a slow tongue that does not waste is pseudobulbar; a wasted, fasciculating tongue is bulbar", "One hemisphere is enough for most cranial nerve nuclei; the lower face and the tongue are the exceptions", "Bilateral corticobulbar loss releases the crying and laughing centers of the brainstem"],
 [S(11, 323, 362), S(4, 152, 160), B(4, 33, 36), B(13, 121, 123), B(14, 125, 128)], synonyms=["corticonuclear tract", "CBT"], mesh_ids=T("tract-corticobulbar"), pathways=["pathway-corticobulbar"], syndromes=["syn-bulbar-vs-pseudobulbar", "syn-facial-palsy-peripheral-vs-central", "syn-als-pattern"],
 territories=["territory-mca-major", "territory-lateral-lenticulostriate", "territory-basilar"], parent="corona-radiata",
 afferents=[("Ventral precentral gyrus and frontal operculum", "origin")],
 efferents=[("Trigeminal motor, facial, ambiguus and hypoglossal nuclei", "mostly via reticular interneurons"), ("Brainstem reticular formation (emotional expression centers)", "corticoreticular fibers")]))

E.append(tract("tract-optic-radiation", "Optic radiation", "projection",
 "The optic radiation carries visual information from the lateral geniculate nucleus to the calcarine cortex, sweeping around the lateral ventricle in the temporal and parietal white matter: the lower-field fibers run directly back through the parietal lobe, while the upper-field fibers loop forward over the temporal horn as Meyer's loop before turning back. The reconstruction shows the whole geniculocalcarine tract from the geniculate body to the occipital pole. Lesions produce homonymous field defects whose shape names the location, a pie-in-the-sky superior quadrantanopia for the temporal loop and an inferior quadrantanopia for the parietal fibers, and the loop is the reason temporal lobectomy risks a field defect.",
 "From the lateral geniculate nucleus through the retrolenticular part of the internal capsule, fanning out as Meyer's loop over the temporal horn (upper field, inferior fibers) and as the direct bundle through the parietal white matter lateral to the atrium (lower field, superior fibers), converging on the calcarine cortex above and below the sulcus, with macular fibers in the middle.",
 "It relays the retinotopically ordered output of the geniculate to the primary visual cortex, keeping the upper and lower fields separate so that partial lesions produce quadrantic defects; fibers from the two eyes are mixed, so radiation lesions produce congruous homonymous defects, and the macular fibers travel centrally to the occipital pole. The sapphire-blue tractography bundle is used to plan temporal lobe surgery, because Meyer's loop reaches within a centimeter or two of the temporal pole, and the radiation is injured in MCA and PCA infarcts, in periventricular leukomalacia and in temporal and parietal tumors, adding a field defect that patients rarely notice until they are tested.",
 ["artery-anterior-choroidal", "artery-mca", "artery-pca"],
 [mview("axial", "tract-optic-radiation-l", "optic radiation sweeping around the lateral ventricle to the calcarine cortex"), mview("coronal", "tract-optic-radiation-r", "Meyer's loop over the temporal horn")],
 "On tractography a fan of fibers from the geniculate body around the atrium and temporal horn to the occipital lobe; on T2 the stratum sagittale is a thin dark band lateral to the atrium; it is not directly visible on routine sequences.",
 [pathol("Temporal lobe resection or MCA inferior division infarct", "MRI", "Lesion of the anterior temporal white matter interrupting Meyer's loop with a contralateral superior quadrantanopia.", sequence="DWI"),
  pathol("Parietal infarct or tumor", "MRI", "Lesion lateral to the atrium in the parietal white matter with a contralateral inferior quadrantanopia and often neglect or sensory signs.", sequence="FLAIR"),
  pathol("Periventricular leukomalacia", "MRI", "Symmetric periventricular white-matter loss around the atria in premature infants, with cerebral visual impairment from radiation damage.", sequence="T2")],
 [("Contralateral superior quadrantanopia", "contralateral", "Interruption of Meyer's loop in the temporal lobe"), ("Contralateral inferior quadrantanopia", "contralateral", "Interruption of the parietal (superior) fibers"), ("Complete congruous homonymous hemianopia", "contralateral", "Interruption of the whole radiation in the retrolenticular capsule or the stratum sagittale")],
 ["Confrontation fields in all four quadrants", "Formal perimetry before and after temporal lobe surgery", "Check the fields in every patient with a posterior MCA or PCA stroke"],
 ["Temporal is superior, parietal is inferior: the loop carries the upper field", "Radiation defects are congruous; tract defects are not", "A temporal lobectomy that reaches too far back cuts Meyer's loop and the patient loses the upper quadrant"],
 [S(11, 333, 336), S(12, 368, 370), S(7, 262, 268), B(6, 47, 52)], synonyms=["geniculocalcarine tract", "Meyer's loop (anterior part)"], mesh_ids=T("tract-optic-radiation"), pathways=["pathway-visual"], syndromes=["syn-homonymous-hemianopia", "syn-mca-inferior-division", "syn-pca-infarct"],
 territories=["territory-mca-temporal", "territory-pca-occipital", "territory-anterior-choroidal-thalamoperforating"],
 afferents=[("Lateral geniculate nucleus", "origin")],
 efferents=[("Calcarine cortex (area 17)", "termination in layer IV")]))

E.append(tract("tract-acoustic-radiation", "Acoustic radiation", "projection",
 "The acoustic radiation is the short bundle from the medial geniculate body to the primary auditory cortex on Heschl's gyrus, running through the sublenticular part of the internal capsule beneath the lentiform nucleus. Because each cochlea is represented in both medial geniculate bodies after the extensive crossing in the brainstem, a unilateral lesion of the radiation does not cause deafness but impairs sound localization and the recognition of speech in noise from the contralateral side, and bilateral lesions cause cortical deafness. The reconstruction shows the bundle passing laterally under the putamen to the superior temporal plane; it is crossed by MCA perforators and by the fibers of the internal capsule and is damaged in lenticulostriate and MCA infarcts.",
 "From the medial geniculate body, laterally and forward through the sublenticular limb of the internal capsule beneath the putamen and the globus pallidus, above the temporal stem, to the transverse temporal gyrus of Heschl in the floor of the Sylvian fissure, a short thick bundle a few centimeters long.",
 "It conveys the tonotopically ordered auditory signal, already binaural after processing in the superior olive, lateral lemniscus and inferior colliculus, to the core auditory cortex, where frequency, intensity and timing are mapped; corticofugal fibers run back in it to the geniculate and colliculus. Because of the bilateral representation, unilateral damage produces subtle deficits (impaired localization, extinction of contralateral sounds on dichotic testing, poorer speech-in-noise perception), and only bilateral interruption, usually from sequential strokes, produces cortical deafness or auditory agnosia. The bundle is one of the last to myelinate and is affected in periventricular injury of prematurity.",
 ["artery-mca", "arteries-lenticulostriate", "artery-anterior-choroidal"],
 [mview("coronal", "tract-acoustic-radiation-l", "acoustic radiation beneath the lentiform nucleus to Heschl's gyrus"), mview("axial", "tract-acoustic-radiation-r", "sublenticular fibers from the medial geniculate body")],
 "On tractography a short lateral bundle from the medial geniculate under the putamen to the superior temporal surface; not visible on conventional MRI.",
 [pathol("Cortical deafness or auditory agnosia (bilateral lesions)", "MRI", "Bilateral lesions of the temporal lobes or the sublenticular capsule from sequential strokes, with absent cortical auditory evoked responses and preserved brainstem responses.", sequence="FLAIR"),
  pathol("MCA or lenticulostriate infarct", "MRI", "Restricted diffusion under the lentiform nucleus with contralateral extinction of sounds and impaired localization, usually with hemiparesis.", sequence="DWI"),
  pathol("Periventricular leukomalacia", "MRI", "Periventricular white-matter loss in premature infants with central auditory processing disorder.", sequence="T2")],
 [("Impaired localization of sounds and speech-in-noise perception on the contralateral side", "contralateral", "Loss of one auditory radiation with preserved bilateral representation"), ("Cortical deafness when bilateral", "bilateral", "Interruption of both radiations"), ("Auditory extinction on dichotic listening", "contralateral", "Reduced cortical input from the contralateral radiation")],
 ["Dichotic listening or simultaneous sound presentation to both ears", "Audiometry and brainstem auditory evoked responses to show that the periphery and brainstem are intact", "Sound localization with eyes closed"],
 ["One acoustic radiation is enough to hear; two are needed to hear well", "Cortical deafness is a bilateral disease with normal audiograms", "The acoustic radiation runs under the putamen: a striatocapsular stroke can dull the hearing on the other side"],
 [S(11, 341), S(12, 366, 368), S(7, 262, 268), B(12, 105, 108)], synonyms=["auditory radiation", "geniculotemporal tract"], mesh_ids=T("tract-acoustic-radiation"), pathways=["pathway-auditory"], syndromes=["syn-hearing-loss", "syn-mca-stem-infarct"],
 territories=["territory-lateral-lenticulostriate", "territory-mca-temporal", "territory-anterior-choroidal-thalamoperforating"],
 afferents=[("Medial geniculate nucleus", "origin")],
 efferents=[("Heschl's gyrus (areas 41 and 42)", "termination"), ("Medial geniculate and inferior colliculus (corticofugal)", "descending fibers")]))

E.append(tract("tract-thalamic-radiation-anterior", "Anterior thalamic radiation", "projection",
 "The anterior thalamic radiation is the bundle of fibers between the anterior and mediodorsal thalamic nuclei and the prefrontal cortex, running through the anterior limb of the internal capsule between the caudate head and the lentiform nucleus. It carries the limbic and executive traffic of the frontal lobe: the anterior nuclei's contribution to the Papez memory circuit, the mediodorsal nucleus's link with the dorsolateral and orbitofrontal cortex, and the corticothalamic feedback that shapes attention and working memory. Lesions of the anterior limb produce apathy, executive dysfunction and memory impairment without weakness, and the radiation is the target of the anterior capsulotomy used for obsessive-compulsive disorder and of anterior thalamic stimulation for epilepsy.",
 "From the anterior and mediodorsal thalamic nuclei forward through the anterior limb of the internal capsule, between the head of the caudate medially and the lentiform nucleus laterally, fanning into the corona radiata to the prefrontal cortex, the anterior cingulate and the orbitofrontal cortex; it runs with the frontopontine fibers.",
 "It is the two-way channel between the thalamus and the prefrontal cortex: the anterior nuclei relay mammillary and hippocampal memory signals to the cingulate and prefrontal cortex, the mediodorsal nucleus relays amygdalar, olfactory and pallidal signals to the orbitofrontal and dorsolateral cortex and mediates working memory and reward-guided decisions, and prefrontal corticothalamic fibers return through it to tune thalamic gating. Interruption disconnects the frontal lobe from the limbic thalamus, producing abulia, poor planning, disinhibition and a diencephalic-type amnesia, the picture of anterior capsular, caudate and anterior thalamic strokes and of the anterior limb lesions seen in schizophrenia research.",
 ["arteries-lenticulostriate", "artery-mca", "artery-aca", "arteries-thalamoperforating"],
 [mview("axial", "tract-thalamic-radiation-anterior-l", "anterior thalamic radiation in the anterior limb of the internal capsule"), mview("coronal", "tract-thalamic-radiation-anterior-r", "fibers from the anterior thalamus to the prefrontal cortex")],
 "Tractography shows a green (anteroposterior) bundle from the anterior thalamus through the anterior limb to the frontal lobe; on FLAIR the anterior limb is a thin dark band between the caudate and the putamen.",
 [pathol("Anterior limb or caudate infarct (recurrent artery of Heubner or lenticulostriate)", "MRI", "Restricted diffusion in the anterior limb and caudate head with abulia, executive dysfunction and confusion, no weakness.", sequence="DWI"),
  pathol("Anterior capsulotomy", "MRI", "Bilateral small lesions of the anterior limb from radiofrequency or focused ultrasound for refractory obsessive-compulsive disorder.", sequence="T1"),
  pathol("Anterior thalamic nucleus stimulation for epilepsy", "MRI", "Electrodes in the anterior thalamic nuclei at the termination of the mammillothalamic tract; the radiation is the route to the cingulate that spreads the effect.", sequence="T1")],
 [("Abulia, apathy and executive dysfunction", "bilateral", "Disconnection of the prefrontal cortex from the mediodorsal and anterior thalamus"), ("Memory impairment", "bilateral", "Interruption of the anterior nucleus limb of the Papez circuit"), ("Disinhibition and personality change", "bilateral", "Disconnection of the orbitofrontal cortex from the mediodorsal thalamus")],
 ["Initiative and spontaneous behavior during the interview", "Verbal fluency, working memory and set shifting", "Delayed recall"],
 ["An anterior limb stroke looks like a frontal lobe stroke: no weakness, no drive", "The anterior thalamic radiation is the anatomy of capsulotomy for obsessive-compulsive disorder", "Anterior limb means thinking and remembering; posterior limb means moving and feeling"],
 [S(12, 364, 370), S(7, 262, 268), S(9, 301, 306), B(7, 62, 63), B(22, 238, 239)], synonyms=["frontothalamic radiation", "anterior limb fibers"], mesh_ids=T("tract-thalamic-radiation-anterior"), pathways=["pathway-papez-limbic", "pathway-basal-ganglia-loops"], syndromes=["syn-wernicke-korsakoff", "syn-aca-infarct"],
 territories=["territory-medial-lenticulostriate", "territory-lateral-lenticulostriate", "territory-anterior-choroidal-thalamoperforating"], parent="internal-capsule",
 afferents=[("Anterior and mediodorsal thalamic nuclei", "thalamocortical fibers"), ("Prefrontal cortex", "corticothalamic fibers")],
 efferents=[("Prefrontal, orbitofrontal and anterior cingulate cortex", "thalamocortical termination"), ("Anterior and mediodorsal thalamus", "corticothalamic termination")]))

E.append(tract("tract-thalamic-radiation-superior", "Superior thalamic radiation", "projection",
 "The superior thalamic radiation carries the fibers between the ventral tier of the thalamus and the sensorimotor cortex through the posterior limb of the internal capsule and the corona radiata: the ventral posterior nuclei's somatosensory projection to the postcentral gyrus and the ventrolateral and ventral anterior nuclei's motor projection to the precentral gyrus and premotor cortex. It is the thalamocortical half of the sensorimotor system, running beside the descending corticospinal fibers, so posterior limb lesions produce sensory and motor deficits together, and thalamocortical disconnection in the corona radiata produces cortical-type sensory loss with an intact thalamus.",
 "From the ventral anterior, ventrolateral and ventral posterior nuclei laterally through the posterior limb of the internal capsule, interdigitating with the corticospinal tract, and upward through the corona radiata to the precentral and postcentral gyri and the paracentral lobule, with the leg fibers posterior and the face fibers anterior in the capsule.",
 "It delivers touch, proprioception, pain and temperature from the ventral posterior nuclei to the somatosensory cortex and the cerebellar and pallidal motor signals from the ventrolateral and ventral anterior nuclei to the motor and premotor cortex, and it returns corticothalamic fibers that regulate thalamic gating and generate sleep spindles and the alpha rhythm through the reticular nucleus. Its interruption produces contralateral hemianesthesia of cortical type (impaired localization, two-point discrimination and graphesthesia with relative preservation of pain) and contributes to ataxia and bradykinesia from loss of the motor thalamic input. It is damaged in lenticulostriate and anterior choroidal infarcts and in periventricular hemorrhage.",
 ["arteries-lenticulostriate", "artery-anterior-choroidal", "artery-mca"],
 [mview("coronal", "tract-thalamic-radiation-superior-l", "superior thalamic radiation from the ventral thalamus to the central gyri"), mview("axial", "tract-thalamic-radiation-superior-r", "thalamocortical fibers in the posterior limb of the internal capsule")],
 "On tractography a superoinferior bundle from the lateral thalamus through the posterior limb to the pre- and postcentral gyri, inseparable from the corticospinal tract on conventional images.",
 [pathol("Striatocapsular or anterior choroidal infarct", "MRI", "Restricted diffusion of the posterior limb with contralateral hemiparesis and hemisensory loss.", sequence="DWI"),
  pathol("Corona radiata infarct with cortical sensory loss", "MRI", "Small deep white-matter infarct interrupting thalamocortical fibers with impaired discriminative sensation and a normal thalamus.", sequence="DWI"),
  pathol("Periventricular hemorrhage of prematurity", "US", "Germinal matrix hemorrhage extending into the periventricular white matter, injuring the descending and ascending capsular fibers with later spastic diplegia.", sequence="n/a")],
 [("Contralateral cortical-type sensory loss", "contralateral", "Interruption of thalamocortical somatosensory fibers"), ("Contralateral hemiparesis with sensory loss (posterior limb)", "contralateral", "Combined injury with the adjacent corticospinal tract"), ("Ataxia and bradykinesia", "contralateral", "Loss of cerebellar and pallidal thalamocortical input")],
 ["Two-point discrimination, graphesthesia and stereognosis", "Strength and tone, since the corticospinal tract is a neighbor", "Coordination on the affected side"],
 ["Sensation reaches the cortex through the posterior limb; a capsular stroke numbs and weakens together", "Cortical sensory loss with a normal thalamus is a white-matter disconnection", "The sleep spindles on an EEG are the superior thalamic radiation talking to itself"],
 [S(12, 364, 370), S(7, 262, 268), S(4, 143, 149), B(4, 33, 38), B(7, 62, 63)], synonyms=["sensorimotor thalamocortical radiation", "posterior limb thalamocortical fibers"], mesh_ids=T("tract-thalamic-radiation-superior"), pathways=["pathway-dcml", "pathway-lateral-spinothalamic", "pathway-cerebellar-circuits"], syndromes=["syn-lacunar-sensorimotor", "syn-anterior-choroidal-infarct", "syn-lacunar-pure-sensory"],
 territories=["territory-lateral-lenticulostriate", "territory-anterior-choroidal-thalamoperforating"], parent="internal-capsule",
 afferents=[("Ventral posterior, ventrolateral and ventral anterior nuclei", "thalamocortical fibers"), ("Sensorimotor cortex", "corticothalamic fibers")],
 efferents=[("Postcentral and precentral gyri, premotor cortex", "thalamocortical termination"), ("Ventral thalamic nuclei and reticular nucleus", "corticothalamic termination")]))

E.append(tract("tract-thalamic-radiation-posterior", "Posterior thalamic radiation", "projection",
 "The posterior thalamic radiation connects the pulvinar and the lateral posterior nucleus with the parietal and occipital association cortex, running through the retrolenticular part of the internal capsule lateral to the atrium of the lateral ventricle, alongside and mixed with the optic radiation. It carries the thalamic contribution to visual attention, spatial perception and the integration of vision with somatosensation, and lesions of this region combine field defects from the optic radiation with neglect, visuospatial disorganization and, on the left, alexia and agraphia. The stratum sagittale that contains it is the corridor for the posterior cerebral and middle cerebral artery watershed and a common site of periventricular leukomalacia and of glioma spread.",
 "From the pulvinar and lateral posterior nucleus backward and laterally through the retrolenticular internal capsule into the stratum sagittale lateral to the atrium and the occipital horn, fanning to the posterior parietal cortex, the angular gyrus, the lateral occipital cortex and the posterior temporal cortex.",
 "The pulvinar receives the superior colliculus, the visual cortex and the parietal cortex and uses this bundle to coordinate attention across the visual field, to bind the features of an attended object and to suppress distracters; the lateral posterior nucleus contributes to the spatial and reaching functions of the superior parietal lobule; and corticothalamic fibers return through it from the parietal and occipital cortex. Because it shares the stratum sagittale with the optic radiation, its lesions add attentional and perceptual deficits to a hemianopia, and disconnection of the pulvinar from the parietal cortex on the right is one of the mechanisms of neglect. It is also the route by which the thalamus reaches the visual word form and angular gyrus regions on the left.",
 ["artery-pca", "artery-mca", "artery-anterior-choroidal"],
 [mview("axial", "tract-thalamic-radiation-posterior-l", "posterior thalamic radiation from the pulvinar to the parieto-occipital cortex"), mview("coronal", "tract-thalamic-radiation-posterior-r", "retrolenticular fibers lateral to the atrium")],
 "Tractography shows a posterior bundle from the pulvinar through the retrolenticular capsule into the parieto-occipital white matter, overlapping the optic radiation; on T2 the stratum sagittale lateral to the atrium contains both.",
 [pathol("Posterior watershed (MCA-PCA) infarct", "MRI", "Restricted diffusion in the parieto-occipital white matter lateral to the atrium with hemianopia, neglect or visuospatial impairment.", sequence="DWI"),
  pathol("Periventricular leukomalacia", "MRI", "Loss of the peritrigonal white matter in ex-premature children with visual perceptual difficulty and field defects.", sequence="T2"),
  pathol("Glioma spreading along the stratum sagittale", "MRI", "FLAIR-bright infiltration of the peritrigonal white matter extending between the temporal, parietal and occipital lobes.", sequence="FLAIR")],
 [("Contralateral neglect and impaired visual attention (right)", "contralateral", "Disconnection of the pulvinar from the parietal attention cortex"), ("Visuospatial disorientation and optic ataxia", "contralateral", "Loss of the lateral posterior-parietal projection"), ("Homonymous field defect", "contralateral", "Involvement of the accompanying optic radiation")],
 ["Line bisection, cancellation and extinction testing", "Visual fields", "Reading and writing when the left side is involved"],
 ["Peritrigonal lesions take away both the seeing and the noticing: hemianopia plus neglect", "The pulvinar is the thalamus of attention; its radiation is the wire", "Periventricular leukomalacia damages this radiation early, which is why ex-premature children have perceptual visual problems"],
 [S(12, 364, 370), S(7, 262, 268), S(11, 333, 336), B(6, 47, 52), B(7, 58, 60)], synonyms=["pulvinar radiation", "retrolenticular thalamocortical fibers"], mesh_ids=T("tract-thalamic-radiation-posterior"), pathways=["pathway-visual"], syndromes=["syn-hemineglect", "syn-homonymous-hemianopia", "syn-watershed-infarct"],
 territories=["territory-mca-parietal", "territory-pca-occipital", "territory-anterior-choroidal-thalamoperforating"], parent="internal-capsule",
 afferents=[("Pulvinar and lateral posterior nucleus", "thalamocortical fibers"), ("Parietal and occipital cortex", "corticothalamic fibers")],
 efferents=[("Posterior parietal, angular and lateral occipital cortex", "thalamocortical termination"), ("Pulvinar", "corticothalamic termination")]))

E.append(tract("tract-corticopontine-frontal", "Frontopontine tract", "projection",
 "The frontopontine tract carries fibers from the prefrontal, premotor and supplementary motor cortex to the pontine nuclei of the same side, traveling through the anterior limb of the internal capsule and the medial fifth of the crus cerebri to end in the basis pontis, from which the pontocerebellar fibers cross into the contralateral cerebellar hemisphere. It is the largest of the corticopontine projections and the frontal lobe's route to the cerebellum, carrying the intended motor plan and the cognitive signals that the posterior cerebellum processes. Its interruption contributes to the ataxia of capsular and midbrain lesions on the side opposite the cerebellar signs (ataxic hemiparesis) and to the cognitive changes of frontal-cerebellar disconnection.",
 "From the prefrontal, premotor and supplementary motor cortex through the corona radiata and the anterior limb of the internal capsule, descending in the medial part of the crus cerebri (medial to the corticospinal fibers) and ending in the ipsilateral pontine nuclei of the basis pontis at all levels.",
 "The tract sends the frontal cortex's motor plans and cognitive commands to the pontine nuclei, whose axons cross in the middle cerebellar peduncle to the contralateral cerebellar cortex, particularly the posterior lobe and Crus I-II, which return a corrected signal through the dentate nucleus and the thalamus; it is the input limb of the cerebrocerebellar loop that lets the cerebellum predict and time both movement and thought. Because the pathway crosses at the pons and the cerebellar outflow crosses again at the superior cerebellar peduncle, a frontopontine lesion produces ataxia on the side of the hemiparesis, the mechanism of the ataxic hemiparesis of capsular and pontine lacunes.",
 ["arteries-lenticulostriate", "artery-mca", "artery-pca", "arteries-pontine", "artery-basilar"],
 [mview("coronal", "tract-corticopontine-frontal-l", "frontopontine fibers from the frontal lobe to the basis pontis"), mview("axial", "tract-corticopontine-frontal-r", "frontopontine tract in the medial crus cerebri")],
 "Tractography shows a bundle from the frontal lobe through the anterior limb and the medial crus into the pons, lying medial to the corticospinal tract in the peduncle; not separable on conventional MRI.",
 [pathol("Ataxic hemiparesis (capsular or pontine lacune)", "MRI", "Small infarct of the posterior limb, corona radiata or basis pontis interrupting corticopontine and corticospinal fibers together, with weakness and ataxia in the same limbs.", sequence="DWI"),
  pathol("Crossed cerebellar diaschisis", "PET", "Hypometabolism of the cerebellar hemisphere opposite a large frontal or capsular lesion from loss of corticopontocerebellar input; MRI may show later cerebellar atrophy.", sequence="n/a"),
  pathol("Pontine glioma", "MRI", "Diffuse pontine expansion infiltrating the corticopontine terminations with ataxia, cranial nerve palsies and long-tract signs.", sequence="T2")],
 [("Ataxia of the limbs on the side of the hemiparesis", "contralateral", "Interruption of the corticopontine input before its crossing, with the cerebellar output crossing back"), ("Impaired motor planning and sequencing", "contralateral", "Loss of premotor and supplementary motor input to the cerebellum"), ("Frontal-cerebellar cognitive changes", "bilateral", "Disconnection of the prefrontal cortex from the posterior cerebellum")],
 ["Finger-nose and heel-shin testing on the weak side; ataxia out of proportion to weakness", "Strength and reflexes", "Executive testing in bilateral or extensive lesions"],
 ["Ataxic hemiparesis is a corticopontine lesion: the ataxia and the weakness sit on the same side because both cross", "The frontal lobe talks to the cerebellum through the pons; the cerebellum answers through the thalamus", "Crossed cerebellar diaschisis is the cerebellum going quiet when its frontopontine input stops"],
 [S(6, 236, 242), S(5, 205, 212), S(7, 262, 268), B(8, 67, 73), B(7, 60, 63)], synonyms=["frontopontine fibers", "corticopontine tract (frontal)"], mesh_ids=T("tract-corticopontine-frontal"), pathways=["pathway-cerebellar-circuits"], syndromes=["syn-lacunar-ataxic-hemiparesis", "syn-cerebellar-hemispheric"],
 territories=["territory-lateral-lenticulostriate", "territory-basilar"], parent="internal-capsule",
 afferents=[("Prefrontal, premotor and supplementary motor cortex", "origin")],
 efferents=[("Ipsilateral pontine nuclei", "termination"), ("Contralateral cerebellar cortex (via pontocerebellar fibers)", "middle cerebellar peduncle")]))

E.append(tract("tract-corticopontine-parietal", "Parietopontine tract", "projection",
 "The parietopontine tract carries fibers from the somatosensory and posterior parietal cortex to the ipsilateral pontine nuclei, descending through the posterior limb and retrolenticular part of the internal capsule and the lateral part of the crus cerebri, lateral to the corticospinal fibers. Together with the temporopontine and occipitopontine fibers it gives the cerebellum the sensory context of movement, the position of the limbs and of visual targets in space, which the cerebellum uses to guide reaching and to update its predictions. Its lesions contribute to the ataxia and dysmetria of parietal and capsular strokes and it is one of the pathways involved in the optic ataxia of parietal damage.",
 "From the postcentral gyrus, the superior and inferior parietal lobules and the parietal operculum through the corona radiata and the posterior part of the posterior limb and retrolenticular capsule, descending in the lateral fifth of the crus cerebri to the pontine nuclei, especially their dorsolateral part.",
 "The tract conveys tactile, proprioceptive and visuospatial information, already processed in the parietal cortex, to the pontine nuclei and thence, after crossing in the middle cerebellar peduncle, to the contralateral cerebellar hemisphere, chiefly the intermediate zone and the posterior lobe; this lets the cerebellum compare the intended movement with the sensed state of the limb and the target and correct it, and it underlies the cerebellar contribution to reaching and to eye-hand coordination. Interruption produces dysmetria and impaired visually guided reaching on the side opposite the lesion, together with the parietal sensory deficits, and it participates in the crossed cerebellar diaschisis that follows parietal strokes.",
 ["artery-mca", "artery-anterior-choroidal", "artery-pca", "artery-basilar", "arteries-pontine"],
 [mview("coronal", "tract-corticopontine-parietal-l", "parietopontine fibers from the parietal lobe to the pons"), mview("axial", "tract-corticopontine-parietal-r", "parietopontine tract in the lateral crus cerebri")],
 "Tractography shows a bundle from the parietal cortex through the posterior capsule and the lateral peduncle into the pons; on conventional MRI it is part of the posterior limb and the lateral crus.",
 [pathol("Parietal or posterior capsular infarct with ataxia", "MRI", "Restricted diffusion of the parietal white matter or the posterior limb with contralateral sensory loss, dysmetria and misreaching.", sequence="DWI"),
  pathol("Midbrain peduncular infarct", "MRI", "Restricted diffusion of the lateral crus cerebri with contralateral hemiparesis and ataxia from combined corticospinal and corticopontine damage.", sequence="DWI"),
  pathol("Crossed cerebellar diaschisis after parietal stroke", "PET", "Contralateral cerebellar hypometabolism from loss of parietopontine input.", sequence="n/a")],
 [("Contralateral dysmetria and misreaching", "contralateral", "Loss of parietal sensory and spatial input to the cerebellum"), ("Ataxic hemiparesis with sensory loss", "contralateral", "Combined injury of parietopontine, thalamocortical and corticospinal fibers in the posterior capsule"), ("Optic ataxia component with parietal lesions", "contralateral", "Disconnection of the parietal visuomotor cortex from the cerebellum and the frontal cortex")],
 ["Finger-nose testing with eyes open and closed", "Reaching to peripheral targets", "Cortical sensory testing"],
 ["The parietal lobe tells the cerebellum where the arm is; without it the cerebellum guesses", "Lateral crus lesions add ataxia to hemiparesis because the parietopontine fibers live there", "Sensory ataxia and cerebellar ataxia coexist in parietal strokes; the eyes-closed test separates them"],
 [S(6, 236, 242), S(5, 212, 218), S(7, 262, 268), B(8, 67, 73), B(7, 58, 60)], synonyms=["parietopontine fibers", "corticopontine tract (parietal)"], mesh_ids=T("tract-corticopontine-parietal"), pathways=["pathway-cerebellar-circuits"], syndromes=["syn-lacunar-ataxic-hemiparesis", "syn-balint"],
 territories=["territory-mca-parietal", "territory-anterior-choroidal-thalamoperforating", "territory-basilar"], parent="internal-capsule",
 afferents=[("Postcentral gyrus and posterior parietal cortex", "origin")],
 efferents=[("Ipsilateral pontine nuclei", "termination"), ("Contralateral cerebellar hemisphere (via pontocerebellar fibers)", "middle cerebellar peduncle")]))

E.append(tract("tract-corticopontine-occipital", "Occipitopontine tract", "projection",
 "The occipitopontine tract, with the temporopontine fibers (the bundle of Turck), carries fibers from the occipital and posterior temporal visual cortex to the pontine nuclei through the retrolenticular internal capsule and the lateral edge of the crus cerebri. It brings the cerebellum the visual motion and target signals needed for smooth pursuit, the visual guidance of locomotion and the visual calibration of the vestibulo-ocular reflex, ending in the dorsolateral pontine nuclei that project to the flocculus, the paraflocculus and the vermis. Its interruption impairs smooth pursuit toward the side of the lesion and the visual control of balance, and it is part of the crossed cerebellar diaschisis that follows occipital and temporal strokes.",
 "From the extrastriate occipital cortex, the temporo-occipital motion area and the posterior temporal cortex through the stratum sagittale and the retrolenticular internal capsule, descending along the lateral border of the crus cerebri to the dorsolateral pontine nuclei and the nucleus reticularis tegmenti pontis.",
 "Visual motion signals from the temporo-occipital motion complex and the visual cortex reach the dorsolateral pontine nuclei through this tract, and the pontine neurons relay them across the middle cerebellar peduncle to the flocculus, the ventral paraflocculus and the oculomotor vermis, which generate the pursuit command and adapt the vestibulo-ocular reflex to visual error; the tract also carries the optic flow information that the cerebellum uses to control walking and posture. Lesions of the pathway produce ipsiversive pursuit deficits (pursuit toward the side of the lesion is impaired, because the cerebellar pursuit signal crosses twice), impaired optokinetic responses and difficulty using vision for balance.",
 ["artery-pca", "artery-mca", "artery-basilar", "arteries-pontine"],
 [mview("axial", "tract-corticopontine-occipital-l", "occipitopontine fibers from the visual cortex to the lateral crus"), mview("coronal", "tract-corticopontine-occipital-r", "occipito-temporopontine tract in the lateral cerebral peduncle")],
 "Tractography shows a lateral bundle from the occipital and posterior temporal lobes along the stratum sagittale and the lateral peduncle into the dorsolateral pons; not visible on conventional MRI.",
 [pathol("Posterior temporal or occipital infarct with pursuit deficit", "MRI", "Restricted diffusion of the temporo-occipital region with impaired smooth pursuit toward the lesion side and a field defect.", sequence="DWI"),
  pathol("Lateral midbrain infarct", "MRI", "Restricted diffusion at the lateral edge of the crus cerebri with pursuit and optokinetic asymmetry and mild contralateral ataxia.", sequence="DWI"),
  pathol("Dorsolateral pontine lesion", "MRI", "Small lesion of the dorsolateral pons (infarct, demyelination) with ipsilateral pursuit impairment and gaze-evoked nystagmus.", sequence="FLAIR")],
 [("Impaired smooth pursuit toward the side of the lesion", "ipsilateral", "Interruption of the double-crossing cortico-ponto-cerebellar pursuit pathway"), ("Asymmetric optokinetic nystagmus", "ipsilateral", "Loss of visual motion input to the cerebellum"), ("Impaired visual guidance of balance and gait", "bilateral", "Loss of optic flow information to the vermis")],
 ["Smooth pursuit of a slowly moving target in each direction", "Optokinetic drum or tape in each direction", "Romberg and tandem gait with eyes open"],
 ["Pursuit is a cortex-pons-cerebellum loop that crosses twice, so the deficit is toward the side of the lesion", "A posterior temporal stroke that impairs pursuit toward itself has cut the occipitopontine tract", "The dorsolateral pontine nuclei are the pursuit relay; the lateral crus is their entrance"],
 [S(6, 236, 242), S(5, 212, 218), S(11, 333, 336), B(11, 96, 100), B(8, 67, 73)], synonyms=["occipito-temporopontine tract", "bundle of Turck (temporopontine)"], mesh_ids=T("tract-corticopontine-occipital"), pathways=["pathway-cerebellar-circuits", "pathway-visual", "pathway-vestibular-vor"], syndromes=["syn-central-vs-peripheral-vertigo"],
 territories=["territory-pca-occipital", "territory-mca-temporal", "territory-basilar"], parent="internal-capsule",
 afferents=[("Extrastriate occipital cortex and the temporo-occipital motion area", "origin")],
 efferents=[("Dorsolateral pontine nuclei and nucleus reticularis tegmenti pontis", "termination"), ("Flocculus, paraflocculus and oculomotor vermis (via pontocerebellar fibers)", "middle cerebellar peduncle")]))

E.append(tract("tract-corticostriatal-anterior", "Corticostriatal tract, anterior", "projection",
 "The anterior corticostriatal bundle groups the fibers from the prefrontal and orbitofrontal cortex to the head of the caudate and the anterior putamen and the ventral striatum, the cortical input of the associative and limbic loops of the basal ganglia. These projections carry the goals, rules and reward expectations that the striatum uses to select behavior, and their targets are the parts of the striatum most affected in obsessive-compulsive disorder, addiction and Huntington disease. The bundle runs through the anterior corona radiata and the external and anterior internal capsule to the striatum, and its interruption or dysfunction produces apathy, disinhibition and impaired habit and reward learning rather than motor signs.",
 "From the dorsolateral, ventrolateral and orbitofrontal prefrontal cortex and the anterior cingulate through the anterior corona radiata, converging on the head of the caudate nucleus, the anterior putamen and the nucleus accumbens through the anterior limb of the internal capsule and the external capsule; the fibers are glutamatergic and topographically organized.",
 "Prefrontal corticostriatal axons synapse on the striatal medium spiny neurons of the direct and indirect pathways in the associative (caudate) and limbic (ventral) striatum, where dopamine from the ventral tegmental area and the medial substantia nigra gates their effect; through the pallidum and the mediodorsal and ventral anterior thalamus the loop returns to the same prefrontal areas, allowing the cortex to learn which actions and strategies are rewarded and to switch between them. The anterior cingulate and orbitofrontal components pass motivation and value; the dorsolateral components pass working memory and rules. Dysfunction of the loop underlies compulsions, apathy and impulse disorders, and its striatal targets degenerate first in Huntington disease.",
 ["arteries-lenticulostriate", "artery-aca", "artery-mca"],
 [mview("coronal", "tract-corticostriatal-anterior-l", "anterior corticostriatal fibers from the prefrontal cortex to the caudate head"), mview("axial", "tract-corticostriatal-anterior-r", "prefrontal fibers converging on the anterior striatum")],
 "Tractography shows a fan from the frontal lobe converging on the caudate head and anterior putamen through the anterior limb and external capsule; not visible on conventional MRI.",
 [pathol("Huntington disease", "MRI", "Caudate head atrophy with enlarged frontal horns and loss of the corticostriatal terminal field; frontal atrophy follows.", sequence="T1"),
  pathol("Caudate infarct (Heubner or lenticulostriate)", "MRI", "Restricted diffusion of the caudate head and anterior limb with abulia, disinhibition and confusion.", sequence="DWI"),
  pathol("Obsessive-compulsive disorder (functional)", "PET", "Hypermetabolism of the orbitofrontal cortex, caudate and thalamus in the anterior loop; structural imaging normal; the anterior limb is the capsulotomy target.", sequence="n/a")],
 [("Apathy and abulia", "bilateral", "Loss of prefrontal drive to the associative striatum"), ("Disinhibition and compulsive behavior", "bilateral", "Dysregulation of the orbitofrontal-ventral striatal loop"), ("Impaired reward and habit learning", "bilateral", "Loss of the corticostriatal substrate of reinforcement learning")],
 ["Initiative, planning and rule shifting", "Impulse control and compulsions history", "Chorea and eye movement testing when Huntington disease is a consideration"],
 ["The anterior striatum is the frontal lobe's habit machine; cut its input and the patient neither starts nor stops", "Huntington disease begins where the prefrontal cortex projects: the caudate head", "Capsulotomy for obsessive-compulsive disorder cuts this bundle in the anterior limb"],
 [S(10, 309, 318), S(7, 262, 268), B(23, 250, 252), B(7, 62, 63)], synonyms=["prefrontal corticostriatal fibers", "associative-limbic corticostriatal projection"], mesh_ids=T("tract-corticostriatal-anterior"), pathways=["pathway-basal-ganglia-loops"], syndromes=["syn-huntington-chorea", "syn-aca-infarct"],
 territories=["territory-medial-lenticulostriate", "territory-lateral-lenticulostriate"], parent="internal-capsule",
 afferents=[("Prefrontal, orbitofrontal and anterior cingulate cortex", "origin")],
 efferents=[("Caudate head, anterior putamen and nucleus accumbens", "glutamatergic termination on medium spiny neurons")]))

E.append(tract("tract-corticostriatal-superior", "Corticostriatal tract, superior", "projection",
 "The superior corticostriatal bundle contains the fibers from the motor, premotor and somatosensory cortex to the putamen and the body of the caudate, the cortical input of the motor loop of the basal ganglia. It descends through the corona radiata to the dorsolateral striatum, where the somatotopic representation of the body in the putamen is built from these terminals, and it is the pathway through which the cortex tells the basal ganglia what movement is planned so that the direct and indirect pathways can release it and suppress its competitors. Its degeneration and its abnormal dopaminergic modulation underlie the motor signs of Parkinson disease and Huntington disease, and it is interrupted in striatocapsular infarcts.",
 "From the precentral and postcentral gyri, the premotor cortex and the supplementary motor area through the corona radiata, entering the putamen and the body of the caudate from above and laterally through the internal and external capsules with a somatotopic order (leg dorsal, face ventral).",
 "Sensorimotor corticostriatal axons excite the medium spiny neurons of the putamen, whose direct-pathway cells then inhibit the internal pallidum to release the movement while indirect-pathway cells increase pallidal output to stop competing movements; dopamine from the substantia nigra strengthens or weakens these corticostriatal synapses according to outcome, making the loop the site of motor habit learning. Copies of the same corticofugal axons continue to the brainstem and spinal cord. Loss of dopamine leaves the corticostriatal input unable to drive the direct pathway, producing bradykinesia; loss of the indirect-pathway striatal neurons in Huntington disease leaves it unopposed, producing chorea; and striatal infarcts produce dystonia and hemichorea.",
 ["arteries-lenticulostriate", "artery-mca"],
 [mview("coronal", "tract-corticostriatal-superior-l", "superior corticostriatal fibers from the sensorimotor cortex to the putamen"), mview("axial", "tract-corticostriatal-superior-r", "sensorimotor fibers entering the dorsolateral striatum")],
 "Tractography shows fibers descending from the central gyri into the putamen and caudate body, mixed with the corona radiata; not separable on conventional images.",
 [pathol("Striatocapsular infarct", "MRI", "Restricted diffusion of the putamen and adjacent capsule with contralateral hemiparesis and, later, dystonia or chorea.", sequence="DWI"),
  pathol("Parkinson disease (functional)", "SPECT", "Reduced dopamine transporter binding in the posterior putamen, the terminal field of the sensorimotor corticostriatal projection, worst contralateral to the affected side.", sequence="n/a"),
  pathol("Huntington disease", "MRI", "Putaminal and caudate atrophy with loss of the indirect-pathway neurons that the sensorimotor cortex drives.", sequence="T1")],
 [("Contralateral bradykinesia when dopaminergic modulation fails", "contralateral", "Ineffective corticostriatal activation of the direct pathway"), ("Contralateral chorea or dystonia after striatal injury", "contralateral", "Loss of indirect-pathway suppression of competing movements"), ("Impaired motor habit learning", "bilateral", "Loss of dopamine-dependent plasticity at corticostriatal synapses")],
 ["Finger tapping and rapid alternating movements", "Observation for chorea and dystonia", "Motor sequence learning where feasible"],
 ["The putamen is the motor cortex's second target; the first is the spinal cord", "The posterior putamen loses dopamine first in Parkinson disease because it is where the motor cortex projects", "Striatal strokes cause movement disorders weeks later, when the corticostriatal synapses reorganize"],
 [S(10, 309, 318), S(7, 262, 268), B(23, 241, 250), B(7, 62, 63)], synonyms=["sensorimotor corticostriatal fibers", "motor loop input"], mesh_ids=T("tract-corticostriatal-superior"), pathways=["pathway-basal-ganglia-loops"], syndromes=["syn-parkinsonism", "syn-huntington-chorea", "syn-hemiballismus"],
 territories=["territory-lateral-lenticulostriate"], parent="internal-capsule",
 afferents=[("Precentral and postcentral gyri, premotor cortex and SMA", "origin")],
 efferents=[("Putamen and body of the caudate", "glutamatergic termination on medium spiny neurons")]))

E.append(tract("tract-corticostriatal-posterior", "Corticostriatal tract, posterior", "projection",
 "The posterior corticostriatal bundle carries fibers from the parietal, temporal and occipital association cortex to the body and tail of the caudate and the posterior putamen, the cortical input of the visual and associative loops of the basal ganglia. These projections bring the striatum the visuospatial, auditory and object information it needs for attention, eye movement selection and the learning of stimulus-response habits, and their targets include the tail of the caudate that curves into the temporal lobe beside the amygdala. The bundle is less familiar than its frontal counterpart but explains the neglect, visual attention deficits and altered saccade selection that accompany posterior striatal and parietal lesions.",
 "From the posterior parietal cortex, the superior and inferior temporal gyri and the extrastriate occipital cortex through the posterior corona radiata and the stratum sagittale, entering the body and tail of the caudate along the lateral ventricle and the posterior putamen through the retrolenticular and external capsules.",
 "Posterior association cortex projects topographically to the caudate body and tail and the posterior putamen, where the striatum learns to associate visual and auditory stimuli with valuable actions and eye movements; through the substantia nigra pars reticulata and the superior colliculus the loop selects the saccade targets that experience has rewarded, and through the pallidum and the thalamus it returns to the parietal and temporal cortex to bias attention toward learned salient objects. The tail of the caudate receives the inferior temporal cortex and holds long-term object values. Interruption impairs visual habit learning, produces subtle neglect and reduces the efficiency of visual search, and the caudate tail is affected in Huntington disease and in temporal lobe pathology.",
 ["arteries-lenticulostriate", "artery-mca", "artery-anterior-choroidal", "artery-pca"],
 [mview("coronal", "tract-corticostriatal-posterior-l", "posterior corticostriatal fibers from the parieto-temporal cortex to the caudate body and tail"), mview("axial", "tract-corticostriatal-posterior-r", "association cortex fibers entering the posterior striatum")],
 "Tractography shows fibers from the parietal and temporal lobes converging on the caudate body and tail and the posterior putamen; the caudate tail itself is a thin gray band in the roof of the temporal horn on coronal T2 images.",
 [pathol("Posterior striatocapsular infarct", "MRI", "Restricted diffusion of the posterior putamen and caudate body with contralateral hemiparesis and attentional deficits.", sequence="DWI"),
  pathol("Huntington disease", "MRI", "Atrophy of the caudate body and tail with flattening of the ventricular wall on coronal images.", sequence="T1"),
  pathol("Temporal lobe pathology involving the caudate tail", "MRI", "Medial temporal tumor or sclerosis distorting the caudate tail in the roof of the temporal horn.", sequence="T2")],
 [("Impaired visual attention and search", "contralateral", "Loss of association cortex input to the visual striatal loop"), ("Altered saccade selection and visual habit learning", "contralateral", "Loss of the caudate-nigra-collicular loop input"), ("Contribution to neglect with parietal lesions", "contralateral", "Disconnection of the parietal attention cortex from the striatum")],
 ["Visual search and cancellation tasks", "Saccade latency to targets in each hemifield", "Extinction testing"],
 ["The caudate tail is where the temporal lobe teaches the basal ganglia which objects are worth looking at", "Posterior corticostriatal fibers are the visual half of the basal ganglia loops", "Neglect has a striatal component: the putamen and caudate are part of the attention network"],
 [S(10, 309, 318), S(7, 262, 268), B(23, 241, 250), B(7, 58, 60)], synonyms=["parieto-temporo-occipital corticostriatal fibers", "visual loop input"], mesh_ids=T("tract-corticostriatal-posterior"), pathways=["pathway-basal-ganglia-loops", "pathway-visual"], syndromes=["syn-hemineglect", "syn-huntington-chorea"],
 territories=["territory-lateral-lenticulostriate", "territory-mca-parietal", "territory-anterior-choroidal-thalamoperforating"], parent="internal-capsule",
 afferents=[("Posterior parietal, temporal and extrastriate occipital cortex", "origin")],
 efferents=[("Body and tail of the caudate and the posterior putamen", "glutamatergic termination on medium spiny neurons")]))

write(E)
